let opsData=null;const statusLabels={requested:'Заявка',quoted:'Сроки предложены',awaiting_payment:'Ожидает оплаты',queued:'В очереди',on_way:'Садовник идёт',working:'Выполняется',review:'Проверка отчёта',done:'Завершено',cancelled:'Отменено'};
const growingLabels={unchecked:'Новая грядка',empty:'Нужна подготовка',ready:'Готова к посадке',planted:'Посеяна',growing:'Растёт',harvest_ready:'Готова к сбору',finished:'Цикл завершён'};
const money=n=>n===null?'Тариф не задан':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(n/100);
const fmt=d=>d?new Date(d).toLocaleString('ru-RU'):'После согласования';
const previousRefresh=refreshCloud,previousRender=render;
refreshCloud=async function(){cloud=await api('state');account=cloud.user;opsData=await api('ops');if(location.hash==='#warehouse')batchData=(await api('batches')).batches;render()};
const menu=document.querySelector('.more-nav');menu.insertAdjacentHTML('beforeend','<a href="#orders">Работы и заказы</a><a href="#services">Услуги и тарифы</a><a href="#notifications">Уведомления</a><a href="#launch">Готовность запуска</a>');
async function loadOperations(){try{opsData=await api('ops');render()}catch(e){toast(e.message)}}
function orderCard(o){let actions='';if(account?.id===o.user_id&&o.status==='quoted')actions+=`<button class="btn" onclick="changeOrder('${o.id}','awaiting_payment')">Согласовать ${money(o.price_kopecks)}</button>`;if(account?.id===o.user_id&&['requested','quoted','awaiting_payment','queued'].includes(o.status))actions+=`<button class="btn light" onclick="changeOrder('${o.id}','cancelled')">Отменить</button>`;if(account?.role==='admin'&&o.status==='requested')actions+=`<button class="btn" onclick="scheduleOrder('${o.id}')">Предложить сроки</button>`;if(account?.id===o.assigned_to){const next={queued:['on_way','Иду к грядке'],on_way:['working','Начать работу'],working:['review','Отправить отчёт']}[o.status];if(next)actions+=`<button class="btn" onclick="changeOrder('${o.id}','${next[0]}')">${next[1]}</button>`}if(account?.role==='admin'&&o.status==='review')actions+=`<button class="btn" onclick="changeOrder('${o.id}','done')">Принять результат</button>`;return `<article class="panel"><div class="row"><span class="pill">№${o.plot_id} · ${statusLabels[o.status]}</span><b>${money(o.price_kopecks)}</b></div><h3>${esc(o.title)}</h3><p>Начало до: ${fmt(o.start_by)}<br>Завершение до: ${fmt(o.finish_by)}<br>Оценка работы: ${o.duration_minutes} мин.</p>${o.status==='awaiting_payment'?'<p class="note">Онлайн-оплата пока не подключена. Платная работа не запустится.</p>':''}${o.report?`<p>${esc(o.report)}</p>`:''}<div class="actions">${actions}<button class="btn light" onclick="orderHistory('${o.id}')">История</button></div></article>`}
function ordersPage(){return heading('За каждой кнопкой — реальная работа.','Заказ, согласование, выполнение и подтверждение результата.')+(!account?'<section class="panel"><p>Войди, чтобы видеть свои заказы.</p><button class="btn" onclick="profile()">Войти</button></section>':!opsData?'<p>Загружаем…</p>':`<div class="grid">${opsData.orders.length?opsData.orders.map(orderCard).join(''):'<section class="panel empty"><h3>Пока нет заказов</h3><p>Выбери работу внутри своей грядки.</p></section>'}</div>`)}
function servicesPage(){return heading('Работы с понятными условиями.','Краснодарский край, Белореченск, ул. Победы, 479')+(!account?'<p>Войди для просмотра услуг.</p>':!opsData?'<p>Загружаем…</p>':`<p class="note">Продолжительность — предварительная оценка. Срок начала назначает управляющий. Оплата пока не подключена.</p><div class="grid">${opsData.services.map(s=>`<article class="panel"><small>${s.enabled?'Доступна для заявок':'Не открыта для заказов'}</small><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="row"><b>${money(s.price_kopecks)}</b><span>~${s.duration_minutes} мин.</span></div>${account.role==='admin'?`<p><button class="btn light" onclick="editService('${s.code}')">Утвердить тариф</button></p>`:''}</article>`).join('')}</div>`)}
function editService(code){const s=opsData.services.find(s=>s.code===code);formAsync('Тариф: '+s.title,`<label>Цена за грядку, ₽<input name="price" type="number" min="0" max="1000000" step="0.01" required value="${s.price_kopecks===null?'':s.price_kopecks/100}"></label><label>Продолжительность, минут<input name="minutes" type="number" min="1" max="1440" required value="${s.duration_minutes}"></label><label>Приём заявок<select name="enabled"><option value="false">Закрыт</option><option value="true">Открыт</option></select></label><p class="note">Нулевой тариф означает работу без оплаты. Утверждай только реальные цены и длительность для этой фермы.</p><button class="btn">Сохранить тариф</button>`,async f=>{await api('service-save',{code,price:Math.round(Number(f.get('price'))*100),minutes:Number(f.get('minutes')),enabled:f.get('enabled')==='true'});await loadOperations()})}
const oldCare=care;care=function(id){if(!account)return oldCare(id);if(!opsData){loadOperations();toast('Загружаем каталог. Повтори через секунду.');return}const p=cloud.plots.find(p=>p.id===id);const key=crypto.randomUUID();formAsync('Работы · грядка №'+id,`<p>Состояние: <b>${growingLabels[p.growing_state]}</b></p><label>Услуга<select name="service">${opsData.services.filter(s=>s.enabled).map(s=>`<option value="${s.code}">${esc(s.title)} — ${money(s.price_kopecks)} · ~${s.duration_minutes} мин.</option>`).join('')}</select></label><p class="note">Цена фиксируется в заявке. Начало и завершение согласуются отдельно. Сервер проверит готовность грядки и ограничения ухода.</p><button class="btn" ${opsData.services.some(s=>s.enabled)?'':'disabled'}>Создать заявку</button>${!opsData.services.some(s=>s.enabled)?'<p>Управляющий ещё не открыл тарифы.</p>':''}`,async f=>{await api('order-create',{plot:id,service:f.get('service'),key});await loadOperations();location.hash='orders'})};
async function changeOrder(id,to){if(to==='review'){formAsync('Отчёт о работе','<label>Что выполнено, материалы, количество и результат<textarea name="reason" required minlength="20" maxlength="4000" rows="6"></textarea></label><button class="btn">Передать на проверку</button>',async f=>{await api('order-update',{id,to,reason:f.get('reason')});await refreshCloud()});return}if(to==='cancelled'){formAsync('Отмена заказа','<label>Причина<input name="reason" required maxlength="300"></label><button class="btn">Подтвердить отмену</button>',async f=>{await api('order-update',{id,to,reason:f.get('reason')});await refreshCloud()});return}try{await api('order-update',{id,to});await refreshCloud();toast('Статус обновлён')}catch(e){toast(e.message)}}
function scheduleOrder(id){formAsync('Предложить время работы','<p class="note">Сейчас можно назначить заказ себе. Время вводится в часовом поясе твоего устройства.</p><label>Начать до<input name="start" type="datetime-local" required></label><label>Завершить до<input name="finish" type="datetime-local" required></label><button class="btn">Предложить сроки</button>',async f=>{await api('order-update',{id,to:'quoted',worker:account.id,start:new Date(f.get('start')).toISOString(),finish:new Date(f.get('finish')).toISOString()});await refreshCloud()})}
async function orderHistory(id){try{const d=await api('order-events',{id});modalForm('История заказа',d.events.map(e=>`<div class="event"><b>${statusLabels[e.event]||esc(e.event)}</b><small>${fmt(e.created_at)}</small><p>${esc(e.details)}</p></div>`).join(''),()=>{})}catch(e){toast(e.message)}}
function inspectPlot(id){formAsync('Осмотр участка №'+id,`<label>Подтверждённое состояние<select name="state">${Object.entries(growingLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Результат осмотра<textarea name="reason" minlength="10" required rows="4"></textarea></label><button class="btn">Подтвердить состояние</button>`,async f=>{await api('plot-inspect',{plot:id,...Object.fromEntries(f)});await refreshCloud()})}
function carePlan(id){const p=opsData?.plans.find(p=>p.plot_id===id);formAsync('План ухода №'+id,`<label>Культура, грунт, условия, операции и дозировки<textarea name="instructions" minlength="20" maxlength="4000" required rows="7">${esc(p?.instructions||'')}</textarea></label><label>Минимальный интервал повторного полива, минут<input name="waterGap" type="number" min="0" max="525600" required value="${p?.water_gap_minutes??''}"></label><label>Минимальный интервал повторной подкормки, минут<input name="feedGap" type="number" min="0" max="525600" required value="${p?.feed_gap_minutes??''}"></label><p class="note">Это ограничения заказов, а не рекомендация поливать или удобрять с такой частотой. Значения должен определить специалист для участка.</p><button class="btn">Утвердить план</button>`,async f=>{await api('care-plan-save',{plot:id,instructions:f.get('instructions'),waterGap:Number(f.get('waterGap')),feedGap:Number(f.get('feedGap'))});await refreshCloud()})}
function notificationsPage(){return heading('События твоего хозяйства.','Статусы заказов и новые результаты работ.')+`<section class="panel">${opsData?.notifications.length?opsData.notifications.map(n=>`<div class="event">${esc(n.message)}<small>${fmt(n.created_at)}</small></div>`).join(''):'Пока нет событий.'}</section>`}
function launchPage(){return heading('Запуск по фактам.','Что подключено, а что ещё нужно подтвердить.')+`<div class="grid"><section class="panel"><h3>Ферма</h3><p>Краснодарский край, Белореченск,<br>ул. Победы, 479</p><p>Часы работы и штат сотрудников: ожидают подтверждения.</p></section><section class="panel"><h3>Система</h3><p>Аккаунты, база, карта, планы и заявки — подключены.</p><p>Тарифы — утверждает владелец.<br>Оплата, камеры и доставка — требуют подключения.<br>Сроки аренды и договорные условия — требуют настройки.</p></section><section class="panel"><h3>Следующие этапы</h3><p>Полная прослеживаемость посадок, семейные права, восстановление доступа, проверка резервного восстановления, логистика и пилот.</p></section><section class="panel"><h3>Безопасность аккаунта</h3><p>Можно завершить все сеансы своего аккаунта.</p><button class="btn light" onclick="logoutEverywhere()">Выйти на всех устройствах</button></section></div>`}
async function logoutEverywhere(){formAsync('Завершить все сеансы?','<p>Потребуется снова войти с паролем на всех устройствах.</p><button class="btn">Завершить сеансы</button>',async()=>{await api('logout-all',{});location.reload()})}
render=function(){const route=location.hash.slice(1)||'home';const pages={orders:ordersPage,services:servicesPage,notifications:notificationsPage,launch:launchPage};if(pages[route]){$('#app').innerHTML=pages[route]();$('#crumb').textContent=({orders:'ЗАКАЗЫ',services:'УСЛУГИ',notifications:'СОБЫТИЯ',launch:'ЗАПУСК'})[route]}else previousRender();if(account?.role==='admin'&&route==='farmer'){$('#app').insertAdjacentHTML('afterbegin','<div class="quick-actions"><a href="#orders">Очередь работ</a><a href="#services">Тарифы</a><a href="#launch">Запуск</a></div>');$('#app').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:24px"><h3>Состояния и планы участков</h3>${cloud.plots.map(p=>`<div class="event row"><span>№${p.id} · ${growingLabels[p.growing_state]}</span><div class="actions"><button class="btn light" onclick="inspectPlot(${p.id})">Осмотр</button><button class="btn light" onclick="carePlan(${p.id})">План ухода</button></div></div>`).join('')}</section>`)}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route))};
setInterval(()=>{if(account&&!document.hidden&&!modal.open&&['orders','notifications'].includes(location.hash.slice(1)))loadOperations()},30000);render();if(account)loadOperations();
